// src/components/LazyComponents.js
import React, { lazy, Suspense } from 'react';
import LoadingSpinner from './UI/LoadingSpinner';
import ErrorBoundary from './ErrorBoundary';

// Route-based lazy loading
const LazyStoryView = lazy(() => 
  import('../pages/StoryView').catch(() => import('../pages/ErrorPage'))
);

const LazyStoryEditor = lazy(() => 
  import('../pages/StoryEditor').catch(() => import('../pages/ErrorPage'))
);

const LazyProfilePage = lazy(() => 
  import('../pages/ProfilePage').catch(() => import('../pages/ErrorPage'))
);

const LazyDashboard = lazy(() => 
  import('../pages/Dashboard').catch(() => import('../pages/ErrorPage'))
);

const LazyExplorePage = lazy(() => 
  import('../pages/ExplorePage').catch(() => import('../pages/ErrorPage'))
);

export const SuspenseWrapper = ({ children, fallback = <LoadingSpinner /> }) => (
  <ErrorBoundary fallback={<div>Error loading content</div>}>
    <Suspense fallback={fallback}>
      {children}
    </Suspense>
  </ErrorBoundary>
);

export const LazyRoutes = {
  StoryView: () => <SuspenseWrapper><LazyStoryView /></SuspenseWrapper>,
  StoryEditor: () => <SuspenseWrapper><LazyStoryEditor /></SuspenseWrapper>,
  ProfilePage: () => <SuspenseWrapper><LazyProfilePage /></SuspenseWrapper>,
  Dashboard: () => <SuspenseWrapper><LazyDashboard /></SuspenseWrapper>,
  ExplorePage: () => <SuspenseWrapper><LazyExplorePage /></SuspenseWrapper>
};
