// src/services/imageOptimizer.js
class ImageOptimizer {
  constructor() {
    this.supportedFormats = ['webp', 'avif', 'jpg', 'png'];
    this.qualitySettings = {
      thumbnail: 30,
      preview: 60,
      full: 85
    };
  }

  // Convert and optimize images
  async optimizeImage(file, quality = 'preview') {
    const imageQuality = this.qualitySettings[quality];

    try {
      // Create optimized versions
      const optimized = await this.createOptimizedVersions(file, imageQuality);

      // Generate responsive sizes
      const responsive = await this.generateResponsiveSizes(optimized);

      return {
        original: optimized.original,
        webp: optimized.webp,
        avif: optimized.avif,
        responsive,
        metadata: {
          size: optimized.size,
          dimensions: optimized.dimensions,
          format: optimized.format
        }
      };
    } catch (error) {
      console.error('Image optimization failed:', error);
      throw new Error(`Image optimization failed: ${error.message}`);
    }
  }

  // Lazy loading component
  createLazyImage(src, alt, className = '', sizes = []) {
    return `
      <img 
        data-src="${src}"
        data-srcset="${this.generateSrcSet(sizes)}"
        sizes="${this.generateSizes(sizes)}"
        alt="${alt}"
        class="lazy-image ${className}"
        loading="lazy"
        decoding="async"
      />
    `;
  }
}

export default new ImageOptimizer();
