**Progressive image loading component:**

```jsx
// src/components/UI/ProgressiveImage.jsx
import React, { useState, useRef, useEffect } from 'react';
import { Blurhash } from 'react-blurhash';

const ProgressiveImage = ({ 
  src, 
  alt, 
  blurhash, 
  className = '', 
  onLoad,
  placeholder = '/images/placeholder.svg'
}) => {
  const [imageLoaded, setImageLoaded] = useState(false);
  const [blurHashLoaded, setBlurHashLoaded] = useState(false);
  const [imageError, setImageError] = useState(false);
  const imgRef = useRef(null);

  useEffect(() => {
    const img = new Image();
    img.src = src;

    img.onload = () => {
      setImageLoaded(true);
      onLoad?.();
    };

    img.onerror = () => {
      setImageError(true);
    };
  }, [src, onLoad]);

  useEffect(() => {
    // Intersection Observer for lazy loading
    if (!imgRef.current) return;

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            const img = entry.target;
            if (img.dataset.src) {
              img.src = img.dataset.src;
              img.srcset = img.dataset.srcset;
              observer.unobserve(img);
            }
          }
        });
      },
      {
        rootMargin: '50px 0px'
      }
    );

    observer.observe(imgRef.current);

    return () => observer.disconnect();
  }, []);

  return (
    <div className={`progressive-image-container ${className}`}>
      {/* Blurhash placeholder */}
      {blurhash && !imageLoaded && (
        <div className="blurhash-container">
          <Blurhash
            hash={blurhash}
            width={400}
            height={300}
            resolutionX={32}
            resolutionY={32}
            punch={1}
            onLoad={() => setBlurHashLoaded(true)}
          />
        </div>
      )}

      {/* Actual image */}
      <img
        ref={imgRef}
        data-src={src}
        alt={alt}
        className={`progressive-image ${imageLoaded ? 'loaded' : 'loading'}`}
        style={{ opacity: imageLoaded ? 1 : 0 }}
        loading="lazy"
        decoding="async"
      />

      {/* Error fallback */}
      {imageError && (
        <img
          src={placeholder}
          alt={alt}
          className="error-image"
        />
      )}
    </div>
  );
};

export default ProgressiveImage;
```

