**Core Web Vitals tracking service:**

```javascript
// src/services/performanceMonitor.js
class PerformanceMonitor {
  constructor() {
    this.metrics = {
      LCP: { value: null, timestamp: null },
      FID: { value: null, timestamp: null },
      CLS: { value: null, timestamp: null },
      FCP: { value: null, timestamp: null },
      TTFB: { value: null, timestamp: null }
    };

    this.observers = new Map();
    this.isMonitoring = false;
  }

  startMonitoring() {
    if (this.isMonitoring) return;

    this.isMonitoring = true;
    this.setupVitalsObservers();
    this.setupResourceTiming();
    this.setupUserTiming();
  }

  setupVitalsObservers() {
    // Largest Contentful Paint (LCP)
    this.observeLCP();

    // First Input Delay (FID)
    this.observeFID();

    // Cumulative Layout Shift (CLS)
    this.observeCLS();

    // First Contentful Paint (FCP)
    this.observeFCP();
  }

  observeLCP() {
    const observer = new PerformanceObserver((list) => {
      const entries = list.getEntries();
      const lastEntry = entries[entries.length - 1];

      this.metrics.LCP = {
        value: lastEntry.startTime,
        timestamp: Date.now()
      };

      this.reportMetric('LCP', this.metrics.LCP.value);
    });

    observer.observe({ entryTypes: ['largest-contentful-paint'] });
    this.observers.set('LCP', observer);
  }

  observeFID() {
    const observer = new PerformanceObserver((list) => {
      for (const entry of list.getEntries()) {
        this.metrics.FID = {
          value: entry.processingStart - entry.startTime,
          timestamp: Date.now()
        };

        this.reportMetric('FID', this.metrics.FID.value);
      }
    });

    observer.observe({ entryTypes: ['first-input'] });
    this.observers.set('FID', observer);
  }

  observeCLS() {
    let clsValue = 0;
    const observer = new PerformanceObserver((list) => {
      for (const entry of list.getEntries()) {
        if (!entry.hadRecentInput) {
          clsValue += entry.value;
        }
      }

      this.metrics.CLS = {
        value: clsValue,
        timestamp: Date.now()
      };

      this.reportMetric('CLS', this.metrics.CLS.value);
    });

    observer.observe({ entryTypes: ['layout-shift'] });
    this.observers.set('CLS', observer);
  }

  observeFCP() {
    const observer = new PerformanceObserver((list) => {
      for (const entry of list.getEntries()) {
        if (entry.name === 'first-contentful-paint') {
          this.metrics.FCP = {
            value: entry.startTime,
            timestamp: Date.now()
          };

          this.reportMetric('FCP', this.metrics.FCP.value);
          break;
        }
      }
    });

    observer.observe({ entryTypes: ['paint'] });
    this.observers.set('FCP', observer);
  }

  // Custom performance marks
  mark(name) {
    performance.mark(name);
  }

  measure(name, startMark, endMark) {
    performance.measure(name, startMark, endMark);
    const measures = performance.getEntriesByName(name, 'measure');
    if (measures.length > 0) {
      this.reportMetric(`USER_${name}`, measures[measures.length - 1].duration);
    }
  }

  // Report metrics to analytics
  reportMetric(metricName, value) {
    // Send to analytics service
    if (typeof gtag !== 'undefined') {
      gtag('event', 'web_vitals', {
        metric_name: metricName,
        value: Math.round(value),
        custom_parameter: {
          metric_name: metricName,
          metric_value: value
        }
      });
    }

    // Send to custom analytics
    this.sendToAnalytics(metricName, value);
  }

  async sendToAnalytics(metricName, value) {
    try {
      await fetch('/api/analytics/performance', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          metric: metricName,
          value,
          timestamp: Date.now(),
          userAgent: navigator.userAgent,
          url: window.location.href
        })
      });
    } catch (error) {
      console.error('Failed to report metric:', error);
    }
  }

  // Get current metrics
  getMetrics() {
    return { ...this.metrics };
  }

  // Stop monitoring
  stopMonitoring() {
    this.observers.forEach(observer => observer.disconnect());
    this.observers.clear();
    this.isMonitoring = false;
  }
}

export default new PerformanceMonitor();
```

