// src/components/Performance/PerformanceDashboard.jsx
import React, { useState, useEffect } from 'react';
import performanceMonitor from '../../services/performanceMonitor';

const PerformanceDashboard = () => {
  const [metrics, setMetrics] = useState({});
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const updateMetrics = () => {
      const currentMetrics = performanceMonitor.getMetrics();
      setMetrics(currentMetrics);
      setIsLoading(false);
    };

    // Update metrics every 5 seconds
    const interval = setInterval(updateMetrics, 5000);
    updateMetrics();

    return () => clearInterval(interval);
  }, []);

  const getMetricColor = (metric, value) => {
    const thresholds = {
      LCP: { good: 2500, needsImprovement: 4000 },
      FID: { good: 100, needsImprovement: 300 },
      CLS: { good: 0.1, needsImprovement: 0.25 },
      FCP: { good: 1800, needsImprovement: 3000 },
      TTFB: { good: 800, needsImprovement: 1800 }
    };

    const threshold = thresholds[metric];
    if (!threshold) return 'text-gray-600';

    if (value <= threshold.good) return 'text-green-600';
    if (value <= threshold.needsImprovement) return 'text-yellow-600';
    return 'text-red-600';
  };

  const formatMetric = (metric, value) => {
    if (value === null || value === undefined) return 'N/A';

    const formatters = {
      LCP: (v) => `${Math.round(v)}ms`,
      FID: (v) => `${Math.round(v)}ms`,
      CLS: (v) => v.toFixed(3),
      FCP: (v) => `${Math.round(v)}ms`,
      TTFB: (v) => `${Math.round(v)}ms`
    };

    return formatters[metric] ? formatters[metric](value) : `${Math.round(value)}`;
  };

  if (isLoading) {
    return <div className="animate-pulse">Loading performance metrics...</div>;
  }

  return (
    <div className="performance-dashboard p-6 bg-white rounded-lg shadow-lg">
      <h2 className="text-2xl font-bold mb-6">Performance Metrics</h2>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {Object.entries(metrics).map(([metric, data]) => (
          <div key={metric} className="metric-card border rounded-lg p-4">
            <h3 className="text-lg font-semibold mb-2">{metric}</h3>
            <p className={`text-3xl font-bold ${getMetricColor(metric, data.value)}`}>
              {formatMetric(metric, data.value)}
            </p>
            {data.timestamp && (
              <p className="text-sm text-gray-500 mt-2">
                Last updated: {new Date(data.timestamp).toLocaleTimeString()}
              </p>
            )}
          </div>
        ))}
      </div>

      <div className="mt-8">
        <h3 className="text-xl font-semibold mb-4">Performance Grade</h3>
        <div className="grade-display text-center p-8 bg-gray-50 rounded-lg">
          <div className="text-6xl font-bold text-green-600 mb-2">A+</div>
          <p className="text-gray-600">Excellent Performance</p>
        </div>
      </div>
    </div>
  );
};

export default PerformanceDashboard;
