// src/services/mobileOptimizer.js
class MobileOptimizer {
  constructor() {
    this.isMobile = this.detectMobile();
    this.touchSupport = 'ontouchstart' in window;
  }

  detectMobile() {
    return /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(
      navigator.userAgent
    );
  }

  // Optimize images for mobile
  optimizeImageForMobile(imageUrl) {
    if (!this.isMobile) return imageUrl;

    // Serve smaller images for mobile
    return imageUrl.replace(/(\.[^.]+)$/, '_mobile$1');
  }

  // Reduce animations on mobile
  getAnimationDuration(baseDuration) {
    if (!this.isMobile) return baseDuration;
    return Math.min(baseDuration * 0.5, 200); // Cap at 200ms
  }

  // Optimize touch interactions
  getTouchOptimizations() {
    if (!this.isMobile) return {};

    return {
      touchAction: 'manipulation',
      WebkitTapHighlightColor: 'transparent',
      userSelect: 'none'
    };
  }

  // Viewport optimization
  getViewportMeta() {
    if (!this.isMobile) return {};

    return {
      width: 'device-width',
      initialScale: 1.0,
      maximumScale: 5.0,
      userScalable: true,
      viewportFit: 'cover'
    };
  }

  // Reduce bundle size for mobile
  shouldLoadFeature(featureName) {
    const mobileFeatures = {
      'heavy-animations': false,
      'advanced-visualizations': false,
      'webgl-effects': false,
      'large-image-galleries': false
    };

    if (!this.isMobile) return true;
    return mobileFeatures[featureName] !== false;
  }
}

export default new MobileOptimizer();
